def effective_limit(value, default=10):
    if value is None:
        return default
    if isinstance(value, int):
        if value < 0:
            raise ValueError('effective_limit must be non-negative')
        if value == 0:
            return None  # zero means disabled
        # positive int overrides default
        return value
    # non-integer or other type? default behavior keep original? spec only mentions int.
    # fallback to original logic maybe
    return value or default
